"""The :ned: and :msg: roles, linking type names to the NED API pages generated by opp_docgen.

The targets come from the nedtags.xml / msgtags.xml tag files that opp_docgen writes next to the API pages.
Documents use short type names (e.g. :ned:`StandardHost`); if a short name is ambiguous, the first type in
the tag file wins. The shared parts link to the API of the version built from the same tree, whose build keeps
its tag files (config.REFS_DIR). When there is no API to link to, the roles render as plain literals.

The diagrams of the API pages are inlined into the pages, so that the types in them link to their pages as in
the HTML output of opp_docgen; as images, they would only open in the lightbox of sphinxcontrib.images.
"""

import html
import os
import posixpath
import re
import shutil
import xml.etree.ElementTree as ElementTree

from docutils import nodes, utils
from sphinx import addnodes
from sphinx.util import logging
from sphinx.util.nodes import split_explicit_title

from . import config

logger = logging.getLogger(__name__)

API_DIR = 'api'
TAG_FILES = {'ned': 'nedtags.xml', 'msg': 'msgtags.xml'}


def read_tags(path):
    names = {}
    for compound in ElementTree.parse(path).getroot().iter('compound'):
        name = compound.findtext('name')
        filename = compound.findtext('filename')
        docname = API_DIR + '/' + os.path.splitext(filename)[0]
        names.setdefault(name, docname)
        short = name.replace('::', '.').rsplit('.', 1)[-1]
        names.setdefault(short, docname)
    return names


class TypeRoles:
    def __init__(self):
        self.tags = {kind: {} for kind in TAG_FILES}

    def load(self, app):
        cfg = config.current()
        if cfg.has_part('api'):
            tag_dir = os.path.join(app.srcdir, API_DIR)
        elif cfg.mode == 'shared' and os.path.isfile(os.path.join(cfg.dev_docs, config.REFS_DIR, TAG_FILES['ned'])):
            tag_dir = os.path.join(cfg.dev_docs, config.REFS_DIR)
        else:
            return
        for kind, filename in TAG_FILES.items():
            path = os.path.join(tag_dir, filename)
            if not os.path.exists(path):
                raise FileNotFoundError(f'{path} is missing; it should have been generated by opp_docgen')
            self.tags[kind] = read_tags(path)

    def role(self, kind):
        def role(name, rawtext, text, lineno, inliner, options=None, content=None):
            has_explicit_title, title, target = split_explicit_title(utils.unescape(text))
            literal = nodes.literal(rawtext, title, classes=['xref', kind])
            cfg = config.current()
            if not self.tags[kind]:
                return [literal], []
            env = inliner.document.settings.env
            docname = self.tags[kind].get(target)
            if docname is None:
                # A sample build documents only a few types.
                if not cfg.sample:
                    logger.warning('unknown %s type: %s', kind.upper(), target, location=(env.docname, lineno))
                return [literal], []
            if not cfg.has_part('api'):
                return [nodes.reference(rawtext, '', literal, refuri=cfg.dev_url(docname + '.html'))], []
            ref = addnodes.pending_xref(rawtext, literal, refdomain='std', reftype='doc', reftarget='/' + docname,
                                        refexplicit=True, refwarn=True, refdoc=env.docname)
            return [ref], []
        return role


def inline_svg(svg, svg_dir, page_dir, alt):
    """Returns the SVG for inlining into a page, with its links (written relative to the SVG, to the .rst
    sources) made relative to the page and pointed to the HTML pages."""
    def relink(match):
        attr, url = match.groups()
        if re.match(r'[a-zA-Z][a-zA-Z0-9+.-]*:', url) or url.startswith('#'):
            return match.group(0)
        target = posixpath.normpath(posixpath.join(svg_dir, url))
        if target.endswith('.rst'):
            target = target[:-len('.rst')] + '.html'
        return f'{attr}="{posixpath.relpath(target, page_dir)}"'
    svg = re.sub(r'^\s*<\?xml[^>]*\?>\s*', '', svg)
    svg = re.sub(r'\b((?:xlink:)?href)="([^"]*)"', relink, svg)
    svg = re.sub(r'\s+target="_top"', '', svg)
    return svg.replace('<svg', f'<svg role="img" aria-label="{html.escape(alt)}"', 1)


def inline_diagrams(app, doctree, docname):
    if not docname.startswith(API_DIR + '/'):
        return
    for image in list(doctree.findall(nodes.image)):
        uri = image['uri']
        if not uri.endswith('.svg'):
            continue
        with open(os.path.join(app.srcdir, uri)) as f:
            svg = inline_svg(f.read(), posixpath.dirname(uri), posixpath.dirname(docname), image.get('alt', ''))
        image.replace_self(nodes.raw('', f'<div class="neddoc-diagram">{svg}</div>', format='html'))


def copy_icons(app, exception):
    """The inlined diagrams refer to the module icons, which no Sphinx directive copies."""
    source = os.path.join(app.srcdir, API_DIR, 'icons')
    if exception is None and app.builder.format == 'html' and os.path.isdir(source):
        shutil.copytree(source, os.path.join(app.outdir, API_DIR, 'icons'), dirs_exist_ok=True)


def setup(app):
    app.connect('doctree-resolved', inline_diagrams)
    app.connect('build-finished', copy_icons)
    roles = TypeRoles()
    app.connect('builder-inited', roles.load)
    for kind in TAG_FILES:
        app.add_role(kind, roles.role(kind))
